#include "ksPanelPercentTask.h"
#include <stdexcept>
#include <iostream>
int main(){using T=ks::PanelPercentTask;using S=T::Stage;using C=T::Child;unsigned cases=0;auto verify=[&](unsigned divisor,unsigned numerator){T t;unsigned reads=0,children=0,used=0;for(;t.stage()!=S::Complete;){if(t.child()!=C::None){C expected=children==0?C::Prefix:children==1?C::Value:C::Suffix;if(children>=3||t.child()!=expected||!t.resumeChild())throw std::runtime_error("child order");++children;continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read)->unsigned{throw std::runtime_error("early read");}))throw std::runtime_error("budget");used+=t.advanceBefore(cost,[&](T::Read r){++reads;return r==T::Read::Divisor?divisor:numerator;});}unsigned product=numerator*100,full=divisor?product/divisor:0,remainder=product-full*divisor;if(reads!=2||children!=3||used!=178||t.divisor()!=divisor||t.numerator()!=numerator||t.product()!=product||t.quotient()!=uint16_t(full)||t.remainder()!=remainder||t.value()!=uint8_t(full)||t.packedResult()!=uint32_t((remainder<<16)|uint16_t(full))||t.resumeChild()||t.advanceBefore(100,[](T::Read){return 0;}))throw std::runtime_error("percent arithmetic/lifecycle/clocks");++cases;};for(unsigned divisor=0;divisor<65536;++divisor)for(unsigned numerator:{0u,1u,100u,65535u})verify(divisor,numerator);for(unsigned numerator=0;numerator<65536;++numerator)for(unsigned divisor:{0u,1u,100u,65535u})verify(divisor,numerator);std::cout<<"PASS: "<<cases<<" pure panel-percent properties\n";}
